using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using MemeManager;
using D=System.Drawing;

static class DuplicateTests {
 static int checks;static void Check(bool value,string name){if(!value)throw new Exception("FAIL: "+name);Console.WriteLine("PASS: "+name);checks++;}
 public static int Run(string root){
  string inputs=Path.Combine(root,"duplicate-inputs");Directory.CreateDirectory(inputs);
  using(var image=new D.Bitmap(240,180))using(var g=D.Graphics.FromImage(image)){g.Clear(D.Color.FromArgb(180,190,210));g.FillEllipse(D.Brushes.DarkSlateBlue,15,20,100,100);g.FillRectangle(D.Brushes.White,140,40,65,90);g.DrawLine(new D.Pen(D.Color.Black,8),20,160,210,140);image.Save(Path.Combine(inputs,"原图.png"),D.Imaging.ImageFormat.Png);image.Save(Path.Combine(inputs,"转格式.jpg"),D.Imaging.ImageFormat.Jpeg);using(var large=new D.Bitmap(480,360))using(var lg=D.Graphics.FromImage(large)){lg.InterpolationMode=D.Drawing2D.InterpolationMode.HighQualityBicubic;lg.DrawImage(image,0,0,480,360);large.Save(Path.Combine(inputs,"放大.png"),D.Imaging.ImageFormat.Png);}}
  using(var image=new D.Bitmap(240,180))using(var g=D.Graphics.FromImage(image)){g.Clear(D.Color.FromArgb(180,190,210));g.FillRectangle(D.Brushes.Black,0,0,110,180);g.FillEllipse(D.Brushes.White,140,0,100,180);image.Save(Path.Combine(inputs,"另一张.png"),D.Imaging.ImageFormat.Png);}
  byte[] gif=Hex("47494638396101000100800000000000FFFFFF21F904000A0000002C000000000100010000020244010021F904000A0000002C00000000010001000002024C01003B");File.WriteAllBytes(Path.Combine(inputs,"变化动图.gif"),gif);File.WriteAllBytes(Path.Combine(inputs,"同首帧不同后帧.gif"),Hex("47494638396101000100800000000000FFFFFF21F904000A0000002C000000000100010000020244010021F904000A0000002C00000000010001000002024401003B"));
  File.WriteAllText(Path.Combine(inputs,"损坏.gif"),"bad");
  var library=new Library(Path.Combine(root,"duplicate-library"));var imported=library.Import(new[]{inputs},null,new HashSet<string>(),CancellationToken.None,n=>{});library.Data.Memes.AddRange(imported.Items);library.Data.Groups.Add(new Group{Id="source-group",Name="原始分组"});var original=library.Data.Memes.Single(x=>x.Name=="原图");original.Uses=99;original.Favorite=true;Grouping.Add(original,"source-group");library.Save();
  Check(DuplicateScanner.Distance(0,ulong.MaxValue)==64&&DuplicateScanner.Distance(15,3)==2,"perceptual hash uses correct Hamming distance");
  var a=DuplicateScanner.Read(library.FileFor(original),original,CancellationToken.None);var jpeg=library.Data.Memes.Single(x=>x.Name=="转格式");var b=DuplicateScanner.Read(library.FileFor(jpeg),jpeg,CancellationToken.None);var larger=library.Data.Memes.Single(x=>x.Name=="放大");var c=DuplicateScanner.Read(library.FileFor(larger),larger,CancellationToken.None);Console.WriteLine("pHash distances: JPEG="+DuplicateScanner.Distance(a.Hashes[0],b.Hashes[0])+", resized="+DuplicateScanner.Distance(a.Hashes[0],c.Hashes[0]));Check(DuplicateScanner.Similar(a,b,4)&&DuplicateScanner.Similar(a,c,4),"perceptual scan finds resized and re-encoded copies");
  var different=library.Data.Memes.Single(x=>x.Name=="另一张");Check(!DuplicateScanner.Similar(a,DuplicateScanner.Read(library.FileFor(different),different,CancellationToken.None),4),"different content with similar colors is not grouped");
  var wrongAspect=new VisualSignature{Width=a.Width,Height=a.Height*2,Hashes=a.Hashes,Edges=a.Edges,Colors=a.Colors,Frames=a.Frames};Check(!DuplicateScanner.Similar(a,wrongAspect,4),"aspect ratio prevents stretched-template false matches");var wrongColor=new VisualSignature{Width=a.Width,Height=a.Height,Hashes=a.Hashes,Edges=a.Edges,Colors=new[]{new[]{0,0,0}},Frames=a.Frames};Check(!DuplicateScanner.Similar(a,wrongColor,4),"color comparison protects equal grayscale hashes");
  var gifA=library.Data.Memes.Single(x=>x.Name=="变化动图");var gifB=library.Data.Memes.Single(x=>x.Name=="同首帧不同后帧");var animA=DuplicateScanner.Read(library.FileFor(gifA),gifA,CancellationToken.None);var animB=DuplicateScanner.Read(library.FileFor(gifB),gifB,CancellationToken.None);Check(animA.Frames==2&&animA.Hashes.Length==3&&!DuplicateScanner.Similar(animA,animB,4),"animated GIF comparison checks later frames instead of first frame alone");
  var broken=new Meme{Id=new string('f',64),Name="missing",Extension=".png"};var snapshot=library.Data.Memes.Concat(new[]{broken}).ToList();int reports=0;var result=DuplicateScanner.Scan(library.Root,snapshot,4,CancellationToken.None,(done,total)=>reports++);Check(result.Groups.Count==1&&result.Groups[0].Items.Count==3&&result.Groups[0].Items[0].Meme.Id==original.Id,"scan groups copies once and suggests keeping most-used image");Check(result.Skipped==1&&reports>0,"scan skips unreadable files and reports progress");
  var cancel=new CancellationTokenSource();cancel.Cancel();bool cancelled=false;try{DuplicateScanner.Scan(library.Root,snapshot,4,cancel.Token,(done,total)=>{});}catch(OperationCanceledException){cancelled=true;}Check(cancelled,"duplicate scan is cancellable without deleting anything");
  int before=library.Data.Memes.Count;byte[] originalJpeg=File.ReadAllBytes(library.FileFor(jpeg));string trash=DuplicateTrash.Remove(library,new[]{jpeg.Id});Check(!File.Exists(library.FileFor(jpeg))&&File.Exists(Path.Combine(trash,jpeg.Id+jpeg.Extension))&&new Library(library.Root).Data.Memes.Count==before-1,"manual duplicate removal moves original to non-C trash and persists database");Check(File.Exists(Path.Combine(inputs,"转格式.jpg"))&&File.Exists(Path.Combine(trash,"manifest.json")),"duplicate cleanup preserves external source and recovery metadata");Check(DuplicateTrash.Restore(library,trash)==1&&File.ReadAllBytes(library.FileFor(jpeg)).SequenceEqual(originalJpeg)&&new Library(library.Root).Data.Memes.Count==before,"undo duplicate removal restores exact original and database");Check(DuplicateTrash.Restore(library,trash)==0,"repeated undo does not duplicate records");
  bool rollback=false;using(var locked=new FileStream(Path.Combine(library.Root,"library.json.tmp"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){try{DuplicateTrash.Remove(library,new[]{original.Id});}catch(IOException){rollback=true;}}Check(rollback&&library.Data.Memes.Count==before&&File.Exists(library.FileFor(original))&&original.Uses==99&&original.Favorite,"failed database save rolls back duplicate file move and metadata");
  string undoFailureTrash=DuplicateTrash.Remove(library,new[]{jpeg.Id});Check(DuplicateTrash.Latest(library)==undoFailureTrash,"recoverable duplicate batch is discoverable after reopening the tool");bool restoreRollback=false;using(var locked=new FileStream(Path.Combine(library.Root,"library.json.tmp"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){try{DuplicateTrash.Restore(library,undoFailureTrash);}catch(IOException){restoreRollback=true;}}Check(restoreRollback&&!File.Exists(library.FileFor(jpeg))&&File.Exists(Path.Combine(undoFailureTrash,jpeg.Id+jpeg.Extension))&&library.Data.Memes.Count==before-1,"failed undo save rolls restored file back into trash");Check(DuplicateTrash.Restore(library,undoFailureTrash)==1,"undo remains usable after a failed attempt");
  string recoveredTrash=DuplicateTrash.Remove(library,new[]{jpeg.Id});library.Data.Memes.Add(jpeg);library.Save();Check(DuplicateTrash.Restore(library,recoveredTrash)==1&&File.Exists(library.FileFor(jpeg))&&library.Data.Memes.Count==before,"undo can recover missing files after metadata backup restoration");
  jpeg=library.Data.Memes.Single(x=>x.Id==jpeg.Id);jpeg.Uses=999;Grouping.Set(jpeg,new string[0]);library.Data.Groups.Add(new Group{Id="family",Name="父组"});library.Data.Groups.Add(new Group{Id="leaf",Name="子组",ParentId="family"});library.Data.Groups.Add(new Group{Id="extra",Name="后来加入"});Grouping.Add(larger,"leaf");library.Save();var preferred=DuplicateScanner.Scan(library.Root,library.Data.Memes,4,CancellationToken.None,(done,total)=>{});Check(preferred.Groups[0].Items[0].Meme.Id==original.Id&&!Grouping.IsGrouped(preferred.Groups[0].Items[1].Meme),"duplicate cleanup prefers ungrouped copies even when they have higher usage");
  var mapping=new Dictionary<string,string>{{larger.Id,original.Id},{jpeg.Id,original.Id}};string mergedTrash=DuplicateTrash.Remove(library,new[]{larger.Id,jpeg.Id},mapping);Check(Grouping.Has(original,"leaf")&&Grouping.Has(original,"source-group")&&library.Data.Memes.Count==before-2,"duplicate cleanup merges removed copies memberships into retained image");Grouping.Add(original,"extra");Grouping.Remove(original,"leaf");library.Data.Groups.RemoveAll(x=>x.Id=="leaf"||x.Id=="family");library.Save();Check(DuplicateTrash.Restore(library,mergedTrash)==2&&Grouping.Has(library.Data.Memes.Single(x=>x.Id==larger.Id),"leaf")&&library.Data.Groups.Single(x=>x.Id=="leaf").ParentId=="family"&&new HashSet<string>(original.GroupIds).SetEquals(new[]{"source-group","extra"}),"undo restores multiple memberships and missing group ancestors while preserving later additions");
  var restoredLarge=library.Data.Memes.Single(x=>x.Id==larger.Id);bool mergeFailed=false;using(var locked=new FileStream(Path.Combine(library.Root,"library.json.tmp"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){try{DuplicateTrash.Remove(library,new[]{restoredLarge.Id},new Dictionary<string,string>{{restoredLarge.Id,original.Id}});}catch(IOException){mergeFailed=true;}}Check(mergeFailed&&!Grouping.Has(original,"leaf")&&File.Exists(library.FileFor(restoredLarge))&&library.Data.Memes.Count==before,"failed duplicate cleanup rolls back transferred group memberships");
  string repeatTrash=DuplicateTrash.Remove(library,new[]{restoredLarge.Id},new Dictionary<string,string>{{restoredLarge.Id,original.Id}});DuplicateTrash.Restore(library,repeatTrash);Grouping.Add(original,"leaf");Check(DuplicateTrash.Restore(library,repeatTrash)==0&&Grouping.Has(original,"leaf"),"repeated undo cannot strip memberships assigned after recovery");
  var backupLarge=library.Data.Memes.Single(x=>x.Id==larger.Id);string backupTrash=DuplicateTrash.Remove(library,new[]{backupLarge.Id});library.Data.Groups.RemoveAll(x=>x.Id=="leaf"||x.Id=="family");Grouping.Remove(original,"leaf");Grouping.Set(backupLarge,new string[0]);library.Data.Memes.Add(backupLarge);library.Save();Check(DuplicateTrash.Restore(library,backupTrash)==1&&Grouping.Has(backupLarge,"leaf")&&library.Data.Groups.Single(x=>x.Id=="leaf").ParentId=="family","undo restores memberships and ancestors when backup metadata already contains the missing image record");
  return checks;
 }
 static byte[] Hex(string hex){return Enumerable.Range(0,hex.Length/2).Select(i=>Convert.ToByte(hex.Substring(i*2,2),16)).ToArray();}
}
